package pe.edu.upeu.pago.controller; import jakarta.validation.Valid; import lombok.RequiredArgsConstructor; import org.springframework.http.*; import org.springframework.web.bind.annotation.*; import pe.edu.upeu.pago.dto.*; import pe.edu.upeu.pago.service.RetiroService; import java.util.*; @RestController @RequestMapping("/api/v1/retiros") @RequiredArgsConstructor public class RetiroController {private final RetiroService service; @GetMapping public List<RetiroResponse> listar(){return service.listar();}@GetMapping("/docente/{id}")public List<RetiroResponse> docente(@PathVariable Long id){return service.porDocente(id);}@PostMapping public ResponseEntity<RetiroResponse> solicitar(@Valid @RequestBody RetiroRequest r){return ResponseEntity.status(201).body(service.solicitar(r));}@PutMapping("/{id}/aprobar")public RetiroResponse aprobar(@PathVariable Long id){return service.aprobar(id);}@PutMapping("/{id}/pagar")public RetiroResponse pagar(@PathVariable Long id,@Valid @RequestBody OperacionRetiroRequest r){return service.pagar(id,r.codigoOperacion());}@PutMapping("/{id}/rechazar")public RetiroResponse rechazar(@PathVariable Long id,@Valid @RequestBody RechazoRequest r){return service.rechazar(id,r.motivo());}}